  "mnemonics": [
    {
      "id": "mn-classer",
      "label": "CLASSE",
      "intro": "Classer la forme compliquée pour décider",
      "entries": [
        {
          "key": "C",
          "term": "Contracture : péritonite — chirurgie immédiate."
        },
        {
          "key": "L",
          "term": "Localement contenu : plastron — antibiothérapie, patience."
        },
        {
          "key": "A",
          "term": "Abcès : collection purulente — drainage."
        },
        {
          "key": "S",
          "term": "Sepsis : réanimation et contrôle de la source."
        },
        {
          "key": "S",
          "term": "Sujet âgé : penser tumeur sous-jacente."
        },
        {
          "key": "E",
          "term": "Évolution : c'est elle qui commande la stratégie."
        }
      ],
      "note": "La forme commande le traitement ; la fièvre et la masse orientent, l'imagerie confirme."
    }
  ],
  "flashcards": [
    {
      "id": "fc-01",
      "front": "Quel délai typique sépare le début de l'appendicite de la perforation ?",
      "back": "Le plus souvent entre 36 et 72 heures d'évolution.",
      "tags": [
        "physiopathologie"
      ]
    },
    {
      "id": "fc-02",
      "front": "Comment définir un plastron appendiculaire ?",
      "back": "Une masse inflammatoire qui enserre le foyer appendiculaire, sans pus franc circulant.",
      "tags": [
        "définitions"
      ]
    },
    {
      "id": "fc-03",
      "front": "Quelle est la prise en charge d'un abcès appendiculaire ?",
      "back": "Drainage (percutané si possible, sinon chirurgical) associé à une antibiothérapie ; appendicectomie différée discutée.",
      "tags": [
        "traitement"
      ]
    },
    {
      "id": "fc-04",
      "front": "Quelle est la prise en charge d'une péritonite appendiculaire ?",
      "back": "Réanimation, antibiothérapie à large spectre et chirurgie de contrôle de la source sans délai.",
      "tags": [
        "urgence"
      ]
    },
    {
      "id": "fc-05",
      "front": "Pourquoi ne pas opérer d'emblée un plastron ?",
      "back": "La dissection d'un plastron inflammatoire expose à des plaies digestives et à des complications pariétales ; on traite d'abord médicalement.",
      "tags": [
        "traitement"
      ]
    },
    {
      "id": "fc-06",
      "front": "Quel examen oriente entre plastron et abcès ?",
      "back": "La tomodensitométrie abdomino-pelvienne (ou l'échographie) qui objective la collection.",
      "tags": [
        "diagnostic"
      ]
    },
    {
      "id": "fc-07",
      "front": "Quand suspecter une tumeur appendiculaire ?",
      "back": "Chez le sujet âgé, devant une appendicite atypique ou une masse appendiculaire ; l'histologie de la pièce est systématique.",
      "tags": [
        "pièges"
      ]
    },
    {
      "id": "fc-08",
      "front": "Que faire devant une fièvre persistante après appendicectomie compliquée ?",
      "back": "Rechercher un abcès résiduel ou une infection pariétale par examen et imagerie.",
      "tags": [
        "surveillance"
      ]
    },
    {
      "id": "fc-09",
      "front": "Quel principe gouverne le sepsis d'origine appendiculaire ?",
      "back": "Le contrôle de la source : l'antibiothérapie seule ne remplace jamais le geste.",
      "tags": [
        "urgence"
      ]
    },
    {
      "id": "fc-10",
      "front": "Quels signes annoncent une appendicite compliquée à l'examen ?",
      "back": "Douleur de plus de 72 heures, fièvre élevée, tachycardie, défense généralisée, masse de fosse iliaque droite, iléus.",
      "tags": [
        "clinique"
      ]
    }
  ],
  "mindmap": {
    "root": {
      "id": "root",
      "label": "Complications de l'appendicite",
      "detail": "La perforation appendiculaire donne trois tableaux : péritonite (chirurgie immédiate), abcès (drainage), plastron (antibiothérapie et chirurgie différée). Le sepsis impose le contrôle de la source."
    },
    "branches": [
